<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
function out(int $s,array $b):void{http_response_code($s);echo json_encode($b);exit;}
$f=__DIR__.'/config.php';if(!is_file($f))out(503,['error'=>'Database configuration is missing.']);$c=require $f;
if(empty($c['setup_key']))out(403,['error'=>'Add setup_key to api/config.php before initial setup.']);$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in)||!hash_equals((string)$c['setup_key'],(string)($in['setupKey']??'')))out(403,['error'=>'Invalid setup key.']);
try{$p=new PDO('mysql:host='.$c['host'].';dbname='.$c['name'].';charset=utf8mb4',$c['user'],$c['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$p->exec('CREATE TABLE IF NOT EXISTS docs (collection VARCHAR(64) NOT NULL,id VARCHAR(100) NOT NULL,data LONGTEXT NOT NULL,updated_at DATETIME(3) NOT NULL,PRIMARY KEY(collection,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');$q=$p->prepare('SELECT data FROM docs WHERE collection=?');$q->execute(['spa_users']);foreach($q as $r){$u=json_decode($r['data'],true);if(($u['role']??'')==='Admin'&&($u['status']??'Active')==='Active')out(409,['error'=>'An active Admin already exists.']);}$name=trim((string)($in['name']??''));$userId=trim((string)($in['userId']??''));$pass=(string)($in['password']??'');if($name===''||$userId===''||strlen($pass)<8)out(400,['error'=>'Name, User ID, and an 8-character password are required.']);$u=['id'=>'u_admin_'.bin2hex(random_bytes(5)),'name'=>$name,'userId'=>$userId,'email'=>trim((string)($in['email']??'')),'role'=>'Admin','status'=>'Active','passwordHash'=>password_hash($pass,PASSWORD_DEFAULT),'mustChangePassword'=>false,'createdAt'=>gmdate('c'),'updatedAt'=>gmdate('c')];$s=$p->prepare('INSERT INTO docs(collection,id,data,updated_at) VALUES(?,?,?,NOW(3))');$s->execute(['spa_users',$u['id'],json_encode($u)]);out(201,['ok'=>true]);}catch(Throwable $e){error_log($e->getMessage());out(500,['error'=>'Setup failed.']);}
